package career.assistant.settings.entity; import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID; @Entity @Table(name="user_settings") public class UserSettings{@Id private UUID id=UUID.fromString("00000000-0000-0000-0000-000000000001");@Column(name="profile_name")private String profileName;private String locations;private String roles;private String skills;@Column(name="experience_min")private Integer experienceMin;@Column(name="experience_max")private Integer experienceMax;@Column(name="dry_run")private boolean dryRun=true;@Column(name="current_location")private String currentLocation="India";private String relocation="UAE";@Column(name="notice_period_days")private Integer noticePeriodDays=90;@Column(name="notification_recipient")private String notificationRecipient="sahana.gowda2227@gmail.com";@Column(name="visa_answer")private String visaAnswer;@Column(name="salary_answer")private String salaryAnswer;@Column(name="sponsorship_answer")private String sponsorshipAnswer;@Column(name="legal_answers")private String legalAnswers;@Column(name="updated_at")private OffsetDateTime updatedAt;@PrePersist @PreUpdate void stamp(){updatedAt=OffsetDateTime.now();}public UUID getId(){return id;}public String getProfileName(){return profileName;}public void setProfileName(String v){profileName=v;}public String getLocations(){return locations;}public void setLocations(String v){locations=v;}public String getRoles(){return roles;}public void setRoles(String v){roles=v;}public String getSkills(){return skills;}public void setSkills(String v){skills=v;}public Integer getExperienceMin(){return experienceMin;}public void setExperienceMin(Integer v){experienceMin=v;}public Integer getExperienceMax(){return experienceMax;}public void setExperienceMax(Integer v){experienceMax=v;}public boolean isDryRun(){return dryRun;}public void setDryRun(boolean v){dryRun=v;}public String getCurrentLocation(){return currentLocation;}public String getRelocation(){return relocation;}public Integer getNoticePeriodDays(){return noticePeriodDays;}public String getNotificationRecipient(){return notificationRecipient;}public String getVisaAnswer(){return visaAnswer;}public String getSalaryAnswer(){return salaryAnswer;}public String getSponsorshipAnswer(){return sponsorshipAnswer;}public String getLegalAnswers(){return legalAnswers;}public OffsetDateTime getUpdatedAt(){return updatedAt;}}
